1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export type Step = QuoteStep | ClaimStep;
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Item {
14	  type: string;
15	  material?: string;
16	  enchantment?: number;
17	  cursed?: boolean;
18	}
19	
20	export interface ClaimStep {
21	  op: "claim";
22	  policy: number;
23	  incident: Incident;
24	}
25	
26	export interface Incident {
27	  cause: string;
28	  damages: Damage[];
29	}
30	
31	export interface Damage {
32	  itemType: string;
33	  amount: number;
34	}
35	
36	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
37	
38	export interface ScenarioResult {
39	  results: StepResult[];
40	}
41	
42	const PROCESSING_FEE = 5;
43	
44	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
45	  sword: 100,
46	  amulet: 60,
47	};
48	
49	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type];
50	
51	export const runScenario = (scenario: Scenario): ScenarioResult => {
52	  const { items } = scenario.steps[0] as QuoteStep;
53	  const basePremium = items.reduce((total, item) => total + basePremiumOf(item), 0);
54	
55	  return { results: [{ premium: basePremium + PROCESSING_FEE }] };
56	};
