1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Base premiums for main items ---
6	  it("quotes an empty item list at 5 G (processing fee only)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	  it("quotes a plain sword at 105 G (100 G base + 5 G fee)", () => {
15	    const result = runScenario({
16	      customer: { yearsWithMHPCO: 0 },
17	      steps: [{ op: "quote", items: [{ type: "sword" }] }],
18	    });
19	
20	    expect(result).toEqual({ results: [{ premium: 105 }] });
21	  });
22	  it("quotes a plain amulet at 65 G (60 G base + 5 G fee)", () => {
23	    const result = runScenario({
24	      customer: { yearsWithMHPCO: 0 },
25	      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
26	    });
27	
28	    expect(result).toEqual({ results: [{ premium: 65 }] });
29	  });
30	  it.todo("quotes a plain staff at 85 G (80 G base + 5 G fee)");
31	  it.todo("quotes a plain potion at 45 G (40 G base + 5 G fee)");
32	
33	  // --- Components and the building block of 3 alike components ---
34	  it.todo("quotes a single rune at 25 G base premium");
35	  it.todo("quotes 2 runes at 50 G base premium");
36	  it.todo("quotes 3 runes at 60 G base premium (block applies)");
37	  it.todo("quotes 4 runes at 100 G base premium (no block — block requires exactly 3)");
38	  it.todo("quotes 7 runes at 175 G base premium (no block — block requires exactly 3)");
39	  it.todo("quotes 2 runes + 1 moonstone at 75 G base premium (no block: different types)");
40	  it.todo("quotes 3 runes + 3 moonstones at 120 G base premium (two separate blocks)");
41	
42	  // --- Item-specific premium modifiers ---
43	  it.todo("adds a 50 % curse surcharge to the cursed item's base premium");
44	  it.todo("adds a 30 % surcharge for enchantment exactly 5");
45	  it.todo("adds no high-enchantment surcharge for enchantment 4");
46	  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5");
47	  it.todo(
48	    "applies the curse surcharge only to the cursed item on a multi-item policy — cursed sword + plain amulet → 210 G before further modifiers and fee",
49	  );
50	
51	  // --- Policy-wide premium modifiers ---
52	  it.todo("applies a 20 % loyalty discount for a customer with exactly 2 years with MHPCO");
53	  it.todo("applies no loyalty discount for a customer with 1 year with MHPCO");
54	  it.todo("applies a 10 % first insurance surcharge to every quote");
55	  it.todo("applies a 15 % follow-up discount to the customer's second quote");
56	
57	  // --- Rounding ---
58	  it.todo("rounds a premium of 197.5 G up to 198 G (in the MHPCO's favour)");
59	  it.todo("rounds a payout of 350.5 G down to 350 G (in the MHPCO's favour)");
60	
61	  // --- Integration examples for the premium ---
62	  it.todo("quotes a newcomer's cursed steel sword (enchantment 3) at 165 G");
63	  it.todo("quotes a 3-year customer's second contract for a cursed sword (enchantment 7) at 160 G");
64	
65	  // --- Claim processing: standard reimbursement ---
66	  it.todo("pays out 400 G for a regular steel sword (enchantment 3) with 500 G damage (full minus 100 G deductible)");
67	  it.todo("pays out 100 G for a damaged rune with 200 G damage (no enchantment or material, so no special clause)");
68	
69	  // --- Claim processing: special clauses ---
70	  it.todo("pays out 400 G for a steel sword with enchantment 9 and 1000 G damage (50 % clause, then deductible)");
71	  it.todo("pays out 700 G for a dragon-material sword with enchantment 5 and 800 G damage (full reimbursement, then deductible)");
72	  it.todo("pays out 400 G for a dragon-material sword with enchantment 8 and 1000 G damage (50 % clause wins, then deductible)");
73	  it.todo("pays out 400 G for a dragon-material sword with enchantment 9 and 1000 G damage (50 % clause wins, then deductible)");
74	
75	  // --- Deductible per damage event ---
76	  it.todo("applies the 100 G deductible once per damaged item — sword 500 G and amulet 300 G → payout 600 G");
77	
78	  // --- Insurance sum and cap ---
79	  it.todo("reports the remaining cap after a claim — sword policy cap 2000 G, 500 G damage → payout 400 G, remaining cap 1600 G");
80	  it.todo("caps a policy of a sword and an amulet at 3200 G (insurance sum 1600 G)");
81	  it.todo("caps a cursed sword policy at 2000 G — premium modifiers do not raise the cap");
82	  it.todo("caps a policy of a sword and 3 runes at 3500 G (insurance sum 1750 G — the block discount affects the premium only)");
83	  it.todo("exhausts the cap over successive claims — two 1500 G claims on a sword policy → payout 1400 G (cap 600 G left), then 600 G (cap 0 G left)");
84	
85	  // --- Multiple items of the same type ---
86	  it.todo("insures two swords at an insurance sum of 2000 G (cap 4000 G)");
87	  it.todo("treats two sword damage entries as separate damages, each with its own deductible");
88	
89	  // --- Errors ---
90	  it.todo("rejects a quote containing an item with an unknown type");
91	  it.todo("rejects a claim whose damage entry references an item not covered by the policy");
92	  it.todo("rejects a claim whose damage entry has an unknown item type");
93	  it.todo("rejects a claim with more damage entries of a type than the policy covers");
94	  it.todo("rejects a claim containing a damage entry with a negative amount");
95	});
